		Scanner sc=new Scanner(System.in);
		int t=sc.nextInt();
		while(t-->0)
		{
		    int n=sc.nextInt();
		    int[] arr=new int[3*n];
		    
		    for(int i=0;i<3*n;i++)
		    {
		        arr[i]=sc.nextInt();
		    }
		        Arrays.sort(arr);
		        for(int i=0;i<arr.length/2;i++)
		        {
		            int temp=arr[i];
		            arr[i]=arr[arr.length-1-i];
		            arr[arr.length-1-i]=temp;
		        }
		        long[] prefix=new long[3*n+1];
		        for(int i=0;i<3*n;i++)
		        {
		            prefix[i+1]=prefix[i]+arr[i];
		        }
		        long answer=0;
		        for(int a=0;a<=n;a++)
		        {
		            int l=0;
		            int h=n-a;
		            while(l<h){
		                int mid=(l+h+1)/2;
		                int b=mid-1;
		                int q=a+2*b;
		                int r=3*n-2*a-b;
		                long change=arr[q]+arr[q+1]-3L*arr[r-1];
		                if(change>=0){
		                    l=mid;
		                }else{
		                    h=mid-1;
		                }
		            }
		            int b=l;
		            int c=n-a-b;
		            int q=a+2*b;
		            int r=q+3*c;
		            long count=0;
		            count+=6L*prefix[a];
		            count+=4L*(prefix[q]-prefix[a]);
		            count+=3L*(prefix[r]-prefix[q]);
		            
		            answer=Math.max(answer,count);
		        }
		        System.out.println(answer);
		    }
		    
		  
		
		
		
	}
